import DeleteOutlineOutlined from '@mui/icons-material/DeleteOutlineOutlined'
import EditOutlined from '@mui/icons-material/EditOutlined'
import { Box, Button, IconButton, Stack, TextField, Tooltip, Typography } from '@mui/material'
import { useState } from 'react'
import type { ActionQueuedPrompt } from '../../../../data/action_run_types'
import {
    deleteActionQueuedPrompt,
    editActionQueuedPrompt,
} from '../../../../services/actions/action_run_registry'
import { dialogService } from '../../../../services/dialog_service'

interface ActionQueuedPromptProps {
    entry: ActionQueuedPrompt
    runId: string
}

/** Editable prompt accepted for later delivery to active agent. */
export function ActionQueuedPromptRow({ entry, runId }: ActionQueuedPromptProps) {
    const [editing, setEditing] = useState(false)
    const [editValue, setEditValue] = useState(entry.content)
    const [saving, setSaving] = useState(false)

    const handleEdit = () => {
        setEditValue(entry.content)
        setEditing(true)
    }
    const handleCancelEdit = () => {
        setEditValue(entry.content)
        setEditing(false)
    }
    const handleSave = async () => {
        if (editValue.trim().length === 0) {
            dialogService.warning('Queued agent prompt cannot be empty')
            return
        }

        setSaving(true)
        try {
            await editActionQueuedPrompt(runId, entry.id, entry.revision, editValue)
            setEditing(false)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not edit queued agent prompt' })
        } finally {
            setSaving(false)
        }
    }
    const handleDelete = async () => {
        try {
            await deleteActionQueuedPrompt(runId, entry.id, entry.revision)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not delete queued agent prompt' })
        }
    }

    return (
        <Box
            aria-label="Queued prompt"
            sx={{
                alignSelf: 'flex-end', bgcolor: 'background.paper', border: 1, borderColor: 'divider',
                borderRadius: 1, flexShrink: 0, maxWidth: '88%', minWidth: 0, overflowWrap: 'anywhere',
                px: 1.25, py: 1,
            }}
        >
            <Stack direction="row" spacing={0.5} sx={{ alignItems: 'center' }}>
                <Typography color="text.secondary" sx={{ flex: 1 }} variant="caption">Queued</Typography>
                {!editing ? (
                    <>
                        <Tooltip title="Edit queued prompt">
                            <IconButton aria-label="Edit queued prompt" onClick={handleEdit} size="small">
                                <EditOutlined sx={{ fontSize: 16 }} />
                            </IconButton>
                        </Tooltip>
                        <Tooltip title="Delete queued prompt">
                            <IconButton aria-label="Delete queued prompt" onClick={handleDelete} size="small">
                                <DeleteOutlineOutlined sx={{ fontSize: 16 }} />
                            </IconButton>
                        </Tooltip>
                    </>
                ) : null}
            </Stack>
            {editing ? (
                <Stack spacing={1}>
                    <TextField
                        autoFocus
                        disabled={saving}
                        multiline
                        onChange={(event) => setEditValue(event.target.value)}
                        size="small"
                        slotProps={{ htmlInput: { 'aria-label': 'Queued prompt content' } }}
                        value={editValue}
                    />
                    <Stack direction="row" spacing={1} sx={{ justifyContent: 'flex-end' }}>
                        <Button disabled={saving} onClick={handleCancelEdit} size="small" variant="outlined">Cancel</Button>
                        <Button disabled={saving} onClick={handleSave} size="small" variant="contained">Save</Button>
                    </Stack>
                </Stack>
            ) : (
                <Typography sx={{ whiteSpace: 'pre-wrap' }} variant="body2">{entry.content}</Typography>
            )}
        </Box>
    )
}
import { Stack } from '@mui/material'
import { useEffect, useMemo, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import { agentAcknowledgementService } from '../../../services/agents/agent_acknowledgement_service'
import { useBoundRunId, useRunSelector } from '../../hooks/use_action_runs'
import {
    ActionConversationTranscript,
} from './transcript/action_conversation_transcript'
import {
    createAcknowledgementConversationSelector,
} from './state/action_conversation_chat_selectors'
import { resolveDisplayedConversation, type ActionConversationStore } from './state/action_conversation_store'
import { ConversationMetaInfo } from './status/conversation_meta_info'
import { ActionConversationCommandService } from './state/action_conversation_command_service'
import type { ActionRunBindingStore } from '../run/state/action_run_binding_store'
import type { ActionUsageValuesService } from '../run/popup/action_usage_values_service'
import type { ActionConversationSearchService } from './search/action_conversation_search_service'

interface ActionConversationChatProps {
    actionId: string
    bindingStore: ActionRunBindingStore
    context: ActionContext
    popupEntryId?: string
    popupVisible?: boolean
    searchService: ActionConversationSearchService
    store: ActionConversationStore
    usageValuesService?: ActionUsageValuesService
}

/** Conversation surface; owns selection, live-run, visibility, and acknowledgement subscriptions. */
export function ActionConversationChat(
    {actionId, bindingStore, context, popupEntryId, popupVisible, searchService, store, usageValuesService}: ActionConversationChatProps,
) {
    const selectAcknowledgementConversation = useMemo(() => createAcknowledgementConversationSelector(), [])
    const commands = useMemo(
        () => new ActionConversationCommandService(actionId, context, store),
        [actionId, context, store],
    )
    const boundRunId = useBoundRunId(bindingStore)
    const liveConversation = useRunSelector(boundRunId, selectAcknowledgementConversation)
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const conversation = resolveDisplayedConversation(liveConversation, selectedConversation)
    const scope = context.cardInternalId ?? null
    const visible = !!popupEntryId && !!popupVisible && !!conversation

    useEffect(() => {
        if (!popupEntryId || !conversation) return undefined

        agentAcknowledgementService.setConversationVisible(popupEntryId, scope, actionId, conversation, visible)

        return () => agentAcknowledgementService.setConversationVisible(
            popupEntryId, scope, actionId, conversation, false,
        )
    }, [actionId, conversation, popupEntryId, scope, visible])

    return (
        <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
            <ActionConversationTranscript
                bindingStore={bindingStore}
                commands={commands}
                searchService={searchService}
                store={store}
            />
            <ConversationMetaInfo bindingStore={bindingStore} store={store} usageValuesService={usageValuesService} />
        </Stack>
    )
}

